design.css:
/* A framed workspace with compact labels and a clear writing panel. */
:scope {
  --tigrana-panel-gap: 12px;
  --tigrana-workspace-inset: 12px;
  --tigrana-panel-radius: 8px;
  --tigrana-panel-shadow: 0 2px 8px #00000012;
  --tigrana-workspace-background: var(--surface-muted);
}
.app-titlebar { background: var(--surface-muted); border-bottom: 0; }
.note-tab { border-radius: 8px; }
.folder-pane, .notes-pane, .unified-tree-pane, .main-pane, .right-sidebar { border: 1px solid var(--tigrana-border); }
.pane-header { color: var(--tigrana-muted); text-transform: uppercase; font-size: 11px; letter-spacing: 0.08em; padding: 14px; border-bottom: 1px solid var(--tigrana-border); }
.topbar { border-bottom: 0; }
.section-view-folder-pane .folder-row { border-radius: 0; margin-right: 6px; }
.note-title-input { font-weight: 700; letter-spacing: -0.04em; }
.ProseMirror h1, .ProseMirror h2, .ProseMirror h3 { font-weight: 650; letter-spacing: -0.015em; }
.ProseMirror blockquote { border-left: 3px solid var(--tigrana-accent); padding: 10px 16px; background: var(--surface-soft); }
.ProseMirror pre, .ProseMirror table { border: 1px solid var(--tigrana-border); }

.pane-resizer { background: transparent; }
.pane-resizer::after { opacity: 0; }
.pane-resizer:hover::after, .pane-resizer:focus-visible::after { opacity: 1; }
